import{_ as i,h as o,i as e,c as n,v as l,p as c,x as r,m as s,e as d,S as p}from"./chunks/framework.Dvtg8yj2.js";const u=JSON.parse('{"title":"机柜作为一块逻辑加速器","description":"","frontmatter":{"title":"机柜作为一块逻辑加速器","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rack-as-accelerator.md","filePath":"llm/rack-as-accelerator.md","lastUpdated":1788454257000}'),A={name:"llm/rack-as-accelerator.md"};function E(B,a,P,h,k,V){const t=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="机柜作为一块逻辑加速器" tabindex="-1">机柜作为一块逻辑加速器 <a class="header-anchor" href="#机柜作为一块逻辑加速器" aria-label="Permalink to &quot;机柜作为一块逻辑加速器&quot;">​</a></h1><div class="epigraph"><p>72 张 GPU 若共享一个 NVLink 域，软件就应当把它们当成一块加速器来切模型，而不是当成 72 台要通过以太网打招呼的主机。</p><footer>—— NVIDIA 对 GB200 NVL72 的公开表述：72-GPU NVLink 域 acts as a single, massive GPU</footer></div><p>上一篇把 <a href="/llm/scale-up-vs-scale-out">Scale-Up 与 Scale-Out</a> 分成两种扩展。本篇只把 Scale-Up 推到编程模型：当机柜（超节点）在互连上已经是一个域，它在逻辑上就是<strong>一块</strong>加速器——有很多 HBM、很多流处理器、一次集体通信覆盖域内全体 GPU。NVIDIA 公开规格里，NVL72 连接 36 个 Grace CPU 与 72 个 Blackwell GPU，液冷机柜，NVLink Switch 提供域内 GPU 通信；硬件用户指南写出 18 个 1U 计算托盘（每托盘 2 Grace + 4 Blackwell）与 9 个 NVLink 交换托盘。本篇据此讨论：进程如何排、内存如何看成域内资源、故障与供电如何按「一台机器」来写。不编造未公开的单通道带宽，也不把某一栏 PFLOPS 抄成自己的测量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统机柜是 20～40 台独立服务器，每台 8 卡，卡间 NVLink，服务器间 InfiniBand。程序员的心理模型是：<code>localhost</code> 上的 8 卡是快的，跨 <code>hostname</code> 是慢的。NVL72 把「快」的范围撑到整柜 72 卡。若调度器仍按「每 8 卡一个推理副本」切片，域内交换机买了却闲着，宽专家、宽 TP、长上下文的 KV 池都跨不出去。若调度器把 72 卡当成无差别的 72 个设备却让集合通信跨出机柜，又把超节点用成了昂贵的 Scale-Out 节点。</p><p>逻辑加速器要回答的问题是：对框架而言，一次 <code>all_reduce</code> 的通信子是整柜还是柜内某子集？HBM 是 72 份不能互相直接读的显存，还是一个能用 NVLink 做远程访问的域？CPU（Grace）与 GPU 的亲和如何绑？答错了，拓扑再漂亮也只是密度更高的 8 卡箱。</p><h3 id="「一块-gpu」是比喻-不是单一-pcie-设备" tabindex="-1">「一块 GPU」是比喻，不是单一 PCIe 设备 <a class="header-anchor" href="#「一块-gpu」是比喻-不是单一-pcie-设备" aria-label="Permalink to &quot;「一块 GPU」是比喻，不是单一 PCIe 设备&quot;">​</a></h3><p>CUDA 仍然看见 72 个 device id。没有把 72 张卡融进一个 <code>cudaSetDevice</code> 就能用 13 TB 级显存的魔法——公开产品页给出机柜级 HBM 总量量级，那是<strong>相加</strong>，不是自动统一寻址的单一指针空间。逻辑加速器的意思是：通信与调度按单域设计，模型并行把整柜当一份权重来切，而不是 9 份互不往来的小模型。统一内存语义若存在，也以厂商编程模型为准，本篇不发明一种「机柜级 malloc」。</p><p><span class="marginnote">公开硬件描述还包含电源架、母线、液冷歧管。它们说明这块逻辑加速器的物理封装是机柜级设施，而不是一张可以插进普通 2U 风冷箱的卡。算法工程师可以不设计母线，但不能在容量规划里假装功耗与风冷 8 卡机相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把一个超节点编成一份模型并行组。TP 度可以超过 8，只要整组 rank 都在该 NVLink 域内。EP 可以把专家铺满 72 卡，decode 时 All-to-All 仍走域内交换。KV 池按整柜 HBM 规划长上下文或高并发，而不是按单托盘 4 卡规划完再在柜内用以太网拼接——柜内根本不应再走一遍数据中心网络去做 TP。进程布局上，计算托盘仍跑 OS，但编排系统应暴露「本柜 NVLink 域」为拓扑标签，禁止把跨柜 GPU 塞进同一 TP 组。</p><p>集合通信在域内走 NVLink Switch。NVIDIA 公开材料把该交换描述为支撑 72 GPU 域、并给出域级聚合带宽规格。对软件，这意味着 NCCL 的 ring / tree 选择应针对「大域、高带宽、短距」而不是「多跳以太网」。跨柜仍然用 Scale-Out 网络做 DP 与存储，不要让检查点流量去抢 NVLink。</p>',12)),(e(),c(p,null,{default:r(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20RACK%5B%22%E9%80%BB%E8%BE%91%E5%8A%A0%E9%80%9F%E5%99%A8%20%3D%20%E4%B8%80%E4%B8%AA%20NVLink%20%E5%9F%9F%22%5D%0A%20%20%20%20T1%5B%22%E8%AE%A1%E7%AE%97%E6%89%98%E7%9B%98%22%5D%0A%20%20%20%20T2%5B%22%E8%AE%A1%E7%AE%97%E6%89%98%E7%9B%98%22%5D%0A%20%20%20%20T18%5B%22%E2%80%A6%2018%20%E6%89%98%E7%9B%98%22%5D%0A%20%20%20%20SW%5B%229%20%E4%B8%AA%20NVLink%20%E4%BA%A4%E6%8D%A2%E6%89%98%E7%9B%98%22%5D%0A%20%20%20%20T1%20---%20SW%0A%20%20%20%20T2%20---%20SW%0A%20%20%20%20T18%20---%20SW%0A%20%20end%0A%20%20RACK%20--%3E%7C%22%E6%A8%A1%E5%9E%8B%E5%B9%B6%E8%A1%8C%20%C2%B7%20%E5%9F%9F%E5%86%85%E9%9B%86%E5%90%88%E9%80%9A%E4%BF%A1%22%7C%20MP%5B%22%E4%B8%80%E4%BB%BD%E5%A4%A7%E6%A8%A1%E5%9E%8B%20%2F%20%E5%AE%BD%20EP%22%5D%0A%20%20RACK%20--%3E%7C%22Scale-Out%20%E7%BD%91%E5%8D%A1%22%7C%20CL%5B%22%E9%9B%86%E7%BE%A4%EF%BC%9A%E5%89%AF%E6%9C%AC%20%C2%B7%20%E5%AD%98%E5%82%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="与推理服务的关系" tabindex="-1">与推理服务的关系 <a class="header-anchor" href="#与推理服务的关系" aria-label="Permalink to &quot;与推理服务的关系&quot;">​</a></h3><p>一块逻辑加速器很适合放<strong>一个</strong>大副本：DeepSeek 级 MoE 的专家铺在域内，MLA 的 KV 按数据并行在域内切，避免跨机 EP 的 decode 延迟，见 <a href="/llm/deepseek-serving">DeepSeek 部署约束</a>。多个小模型则应在域内做 MIG 式切分或显式设备集隔离，避免 72 卡被一个 7B 占满。OpenAI 兼容网关看到的仍是 <code>model</code> 字符串；后面是整柜一份权重还是柜内多份副本，属于调度，不应泄漏进 <a href="/llm/openai-compat-api">协议</a> 字段。</p><p>Prefill / decode 分离可以发生在超节点内部（一部分托盘做 prefill，一部分做 decode），KV 传输走 NVLink 而不是机柜外网络。这比跨机 PD 分离更接近「一块加速器上的两个队列」。是否值得拆，取决于负载是否真的互相拖累，而不是因为机柜看起来像集群。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>逻辑加速器成立，靠的是域内任意 GPU 对之间的通信不再经过数据中心叶子。公开结构里，交换托盘承担机柜级交叉：计算托盘通过背板连到交换托盘，而不是托盘两两直连成一张不完整的图。于是「机柜脊」是 NVLink 交换，不是 Top-of-Rack 以太网。以太网 / IB 网卡仍在，但它们的职责是柜外。编程时若把 NCCL_SOCKET 当域内默认路径，等于绕开这块加速器的脊。</p><p>内存方面，每张 GPU 的 HBM 仍是近端最快；经 NVLink 读远端 HBM 有代价，但代价按加速器互连计，而不是按 RDMA 网卡计。权重可以按 TP 分片常驻近端；KV 与激活是否远程，要看实现是否做了显式迁移。把「130 TB/s」之类官方聚合规格理解成「任意 kernel 都能以该速率扫全部 HBM」是错的——那是互连规格，不是单核访存屋顶线。</p><p><span class="marginnote">Grace CPU 在公开配置里与 GPU 成对出现在托盘中，承担主机侧、部分流水与 I/O。逻辑加速器包含 CPU 内存与 GPU HBM 两层，不要把机柜只数成 72 个 CUDA device 而忽略宿主亲和。具体一致性模型以 NVIDIA 编程指南为准。</span></p><h3 id="故障、维护与爆炸半径" tabindex="-1">故障、维护与爆炸半径 <a class="header-anchor" href="#故障、维护与爆炸半径" aria-label="Permalink to &quot;故障、维护与爆炸半径&quot;">​</a></h3><p>交换托盘或背板故障影响的是整块逻辑加速器的带宽或连通性，而不是「少一台 8 卡服务器」。维护窗口应按机柜设计：固件、液冷、电源架都是柜级。集群调度应能把该柜从副本集摘掉，而不是在半通的 NVLink 域上继续跑 64 路 TP 并抱怨 NCCL 超时。这与把机柜当独立刀片热拔 GPU 的运维手册不兼容，需要新的 runbook。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>比喻的边界：操作系统调度、容器、NUMA、PCIe 设备树仍然是分托盘的。Kubernetes 若按 Pod 绑 8 卡，不理解柜级域，会把逻辑加速器切碎。需要设备插件或拓扑管理器把「NVL 域」当可分配资源。昇腾超节点若也走「机柜一域」路线，软件故事类似，但托盘数、交换与 CANN 编程模型以华为文档为准，不能把 NVL72 的 18+9 抄过去。</p><p>不要用逻辑加速器当借口取消 Scale-Out：训练数据、多副本高可用、跨地域仍然要机柜间网络。不要在文中填写未公开的铜缆眼图或未发布的 NVLink 修订速率。不要把「一块 GPU」写成可以忽略 TP 切分——72 卡仍要切，只是切完之后通信还在域内。</p><p><span class="marginnote">下一篇树节点会写 GB200 / GB300 NVL72 的产品细节。本篇只锁定形态：机柜 = 域 = 一块逻辑加速器。带宽与算力以 NVIDIA 当时公开表为准，不在这里复制整张规格以免过期。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>当 NVLink 域覆盖整柜时，模型并行应把该柜当一份加速器来切，而不是当 9 个 8 卡节点。</li><li>CUDA 设备仍然是多 id；「一块」指通信域与调度单位，不是单个 PCIe 功能。</li><li>NVL72 的公开封装是 18 计算托盘 + 9 交换托盘 + 液冷与柜级供电。</li><li>推理适合在域内放宽 EP / 长 KV 的大副本；小模型要显式切分，避免浪费整柜。</li><li>故障与维护按柜级爆炸半径来写；柜外仍走 Scale-Out。</li><li>出处：NVIDIA GB200 NVL72 产品页与 DGX GB Rack 硬件指南中的域与托盘描述。</li></ul>',15))])}const m=i(A,[["render",E]]);export{u as __pageData,m as default};
